import {CITIES,normalizeCity} from './places.js';
import {esc} from './weather-tools.js';
import {distanceKm} from './nearby-tools.js';
import {HAIL_SIZE_LABELS,hailObserved,hailReportState,sharedHailURL} from './hail-tools.js';
import {createHailWatch} from './hail-watch.js';
export const hailAge=(time,now=Date.now())=>{const m=Math.max(0,Math.floor((now-time)/60000));return m<1?'meno di 1 min fa':m+' min fa'};
export function mapHailReports(data,place,{minutes=120,radius=50,ended='all',size='all'}={},now=Date.now()){
 const fresh=!!data&&Array.isArray(data.posts)&&Number.isFinite(data.updated)&&now-data.updated<=90000&&data.updated<=now+60000;
 const groups=new Map(),unplaced=[];if(!fresh)return {fresh:false,points:[],unplaced,shown:0};
 for(const p of data.posts){if(!p||!Number.isFinite(p.created)||p.created>now||!Number.isFinite(hailObserved(p))||hailObserved(p)>now||hailObserved(p)<=now-minutes*60000||p.expires!=null&&p.expires<=now)continue;
  if(ended==='open'&&p.ended||ended==='ended'&&!p.ended||size!=='all'&&p.size!==size)continue;
  let position=null,origin='';
  if(Number.isInteger(p.map_lat)&&Number.isInteger(p.map_lon)&&Math.abs(p.map_lat)<=8500&&Math.abs(p.map_lon)<=18000){position={latitude:p.map_lat/100,longitude:p.map_lon/100};origin='Zona approssimata dichiarata'}
  else{const c=CITIES.find(c=>normalizeCity(c.name)===normalizeCity(p.city));if(c){position=c;origin='Centro della città dichiarata'}}
  if(!position){unplaced.push(p);continue}const km=distanceKm(place,position);if(!Number.isFinite(km)||radius&&km>radius)continue;
  const key=normalizeCity(p.city)+'|'+position.latitude+'|'+position.longitude;
  if(!groups.has(key))groups.set(key,{...position,id:'hail:'+key,name:p.city,origin,distance:km,reportCount:0,lastReport:hailObserved(p),posts:[],selected:false});
  const group=groups.get(key);group.reportCount++;group.lastReport=Math.max(group.lastReport,hailObserved(p));group.posts.push(p);
 }
 const points=[...groups.values()].sort((a,b)=>b.lastReport-a.lastReport);return {fresh,points,unplaced,shown:points.reduce((n,p)=>n+p.reportCount,0)};
}
export function createHailMap(ctx){
 let data=null,error='',busy=false,sequence=0,user='',minutes=120,radius=50,ended='all',size='all',visible=false;
 const state=()=>mapHailReports(data,ctx.get().place,{minutes,radius,ended,size});
 const watch=createHailWatch({...ctx,data:()=>data});
 function controls(){return `<section class="map-hail-controls" aria-label="Filtri grandine" ${visible?'':'hidden'}><div class="hail-map-heading"><div><p class="hail-eyebrow">METEOSOCIAL / GRANDINE</p><h2>Cosa viene osservato nella tua zona</h2><p>Testimonianze delle persone. Ricontrollo ogni 30 secondi con mappa visibile.</p></div><button class="hail-primary" data-quick="Grandine">◇ Segnala grandine</button></div><div class="map-hail-filters"><label>Quando<select id="map-hail-minutes">${[[15,'Ultimi 15 minuti'],[60,'Ultima ora'],[120,'Ultime 2 ore']].map(([n,t])=>`<option value="${n}" ${minutes===n?'selected':''}>${t}</option>`).join('')}</select></label><label>Distanza da ${esc(ctx.get().place.name)}<select id="map-hail-radius">${[2,5,10,25,50,0].map(n=>`<option value="${n}" ${radius===n?'selected':''}>${n?'Entro '+n+' km':'Tutte le zone disponibili'}</option>`).join('')}</select></label><button data-map-hail-refresh>Aggiorna ora</button><button data-map-hail-share>Condividi questa zona</button></div><details class="hail-extra-filters"><summary>Filtra dimensioni e aggiornamenti</summary><div class="map-hail-filters"><label>Dimensione dichiarata<select id="map-hail-size"><option value="all">Tutte le dimensioni</option>${Object.entries(HAIL_SIZE_LABELS).map(([id,label])=>`<option value="${id}" ${id===size?'selected':''}>${label}</option>`).join('')}</select></label><label>Stato dell’osservazione<select id="map-hail-ended">${[['all','Tutte le osservazioni'],['open','Senza una fine riferita'],['ended','L’autore riferisce: ha smesso']].map(([id,label])=>`<option value="${id}" ${id===ended?'selected':''}>${label}</option>`).join('')}</select></label></div></details>${ctx.get().route==='mondo'?'<p><a href="#grandine-mappa">Apri la mappa per vedere insieme radar e segnalazioni →</a></p>':`<label class="hail-radar-toggle"><input type="checkbox" id="hail-radar-compare" ${ctx.radarEnabled?.()?'checked':''}> Mostra anche il radar delle precipitazioni</label><p class="hail-map-note">Radar e testimonianze hanno orari distinti. I pin restano filtrati per l’ora osservata: non seguono la riproduzione radar.</p>`}<div id="map-hail-overview"></div><p id="map-hail-status" role="status"></p></section>`}
 function overview(){const s=state(),reports=s.points.flatMap(p=>p.posts),endedCount=reports.filter(p=>p.ended).length,disputed=reports.filter(p=>p.disputes>0).length;return `<div class="hail-evidence-counters"><div><b>${s.fresh?s.shown:'—'}</b><span>segnalazioni nei filtri</span></div><div><b>${s.fresh?endedCount:'—'}</b><span>con fine riferita dall’autore</span></div><div><b>${s.fresh?disputed:'—'}</b><span>con osservazioni discordanti</span></div></div><p>Nessuna segnalazione non significa assenza di grandine. Conferme e contestazioni non certificano il fenomeno.</p>`}
 function list(){const s=state();return `<section class="map-hail-list" ${visible?'':'hidden'}><h2>Le stesse segnalazioni, in elenco</h2><p>Pin e lista usano gli stessi filtri. Distanze approssimate dal centro selezionato, non dai bordi del temporale.</p>${!s.fresh?'<p>Segnalazioni non disponibili o da aggiornare. Puoi consultare il bollettino e riprovare.</p>':s.points.length?`<div class="map-hail-rows">${s.points.map(p=>`<button data-map-hail-zone="${esc(p.id)}"><span><strong>◇ ${esc(p.name)}</strong><small>${p.reportCount} segnalazioni · osservazione più recente ${hailAge(p.lastReport)}<br>${esc(p.origin)} · circa ${Math.round(p.distance)} km<br>${p.posts.some(p=>p.disputes>0)?'Ci sono testimonianze discordanti':'Testimonianze da verificare'}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`:'<p>Nessuna segnalazione posizionabile con questi filtri. Può mancare chi osserva: non indica assenza di rischio.</p>'}${s.unplaced.length?`<details><summary>${s.unplaced.length} segnalazioni senza una zona associabile</summary><p>Non entrano nei filtri di distanza o nei pin. Non scegliamo una posizione a caso per un nome ambiguo.</p>${s.unplaced.slice(0,30).map(p=>`<p><a href="#post:${encodeURIComponent(p.id)}">${esc(p.city)} · ${hailAge(hailObserved(p))} →</a></p>`).join('')}${s.unplaced.length>30?'<p>Mostrate le 30 più recenti senza posizione.</p>':''}</details>`:''}${data?.truncated?'<p>Campione limitato alle 500 segnalazioni di grandine più recenti. Altre potrebbero non comparire.</p>':''}<div class="map-hail-links"><button data-map-hail-ai>Spiega la zona con Lente IA</button><a href="#grandine">Quadro completo e fonti →</a><a href="#ripari">Luoghi coperti da verificare →</a><a href="#radar">Apri il radar →</a></div></section>`}
 function paint(){if(!visible)return;const status=document.querySelector('#map-hail-status');if(status){const s=state();status.textContent=busy?'Aggiornamento delle segnalazioni…':error||(!s.fresh?'Dati da aggiornare.':`Ultimo controllo ${new Date(data.updated).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} · ora del dispositivo.`)}const host=document.querySelector('#atlas-hail-list');if(host){const html=list();if(host.innerHTML!==html)host.innerHTML=html}const counts=document.querySelector('#map-hail-overview');if(counts)counts.innerHTML=overview();bindList();watch.paint()}
 function bindList(){document.querySelectorAll('[data-map-hail-zone]').forEach(b=>b.onclick=()=>{const p=state().points.find(p=>p.id===b.dataset.mapHailZone);if(p)open(p)});const ai=document.querySelector('[data-map-hail-ai]');if(ai)ai.onclick=()=>ctx.askAI('Confronta le previsioni, il bollettino e le segnalazioni di grandine della città selezionata. Cosa sappiamo e cosa non possiamo dedurre? Non hai letto i pixel radar. Non trasformare le conferme o le dimensioni dichiarate in una probabilità di grandine.')}
 function open(p){const latest=state().points.find(x=>x.id===p.id);if(!latest){ctx.toast('Questa zona non è più visibile con i filtri attuali. Aggiorna la mappa.');return}ctx.modal(latest.name,`<p><b>Grandine dichiarata dalle persone</b></p><p>${esc(latest.origin)}. Le distanze non indicano una traiettoria.</p><div class="hail-report-cards">${latest.posts.slice(0,12).map(x=>`<article><span class="hail-report-state">${esc(hailReportState(x))}</span><h3>${esc(HAIL_SIZE_LABELS[x.size]||HAIL_SIZE_LABELS.unknown)}</h3><p>Osservata ${hailAge(hailObserved(x))} · pubblicata ${hailAge(x.created)}</p>${x.ended?`<p>Fine riferita ${hailAge(x.ended)}: vale per il punto di osservazione dell’autore.</p>`:''}<p>${esc(x.text||'Apri il post per leggere la testimonianza.')}</p>${x.has_photo?`<details><summary>Foto allegata dall’autore</summary><img class="hail-report-photo" src="/api/photo/${encodeURIComponent(x.id)}" alt="Foto della segnalazione, non verificata" loading="lazy"></details>`:''}<p>${Number(x.confirms)||0} conferme · ${Number(x.disputes)||0} contestazioni</p><p class="hail-map-note">Dichiarazioni degli account; la presenza sul posto non è verificata.</p><div class="hail-report-actions">${x.mine?x.ended?'':`<button type="button" data-hail-end="${esc(x.id)}">Qui ha smesso</button>`:`<button type="button" data-hail-vote="confirm" data-hail-id="${esc(x.id)}" aria-pressed="${x.my_vote==='confirm'}">Confermo l’osservazione</button><button type="button" data-hail-vote="dispute" data-hail-id="${esc(x.id)}" aria-pressed="${x.my_vote==='dispute'}">Non riscontro l’evento</button>`}<a href="#post:${encodeURIComponent(x.id)}" data-hail-open-post>Apri il post e rispondi →</a></div><p data-hail-action-status="${esc(x.id)}" role="status"></p></article>`).join('')}</div>${latest.posts.length>12?'<p>Mostrate le 12 osservazioni più recenti della zona.</p>':''}<button type="button" id="hail-map-dossier" class="button">Previsioni e fonti per questa zona</button>`,null);
 document.querySelectorAll('[data-hail-open-post]').forEach(a=>a.onclick=()=>document.querySelector('#dialog').close());document.querySelector('#hail-map-dossier').onclick=()=>{document.querySelector('#dialog').close();ctx.select(latest);location.hash='grandine'};
 const reportCards=document.querySelector('.hail-report-cards');document.querySelectorAll('.hail-report-photo').forEach(img=>img.onerror=()=>{img.hidden=true;img.parentElement.insertAdjacentHTML('beforeend','<p>Foto non disponibile. Puoi leggere la testimonianza.</p>')});
 document.querySelectorAll('[data-hail-vote]').forEach(b=>b.onclick=async()=>{if(!ctx.get().me)return ctx.login();const report=latest.posts.find(p=>p.id===b.dataset.hailId),article=b.closest('article'),buttons=article.querySelectorAll('button'),status=article.querySelector('[role=status]');buttons.forEach(b=>b.disabled=true);try{await ctx.api('link',{target:report.id,kind:b.dataset.hailVote,active:report.my_vote!==b.dataset.hailVote});sequence++;busy=false;data=null;await load(true);if(reportCards?.isConnected&&document.querySelector('#dialog')?.open)open(latest)}catch(e){status.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}});
 document.querySelectorAll('[data-hail-end]').forEach(b=>b.onclick=()=>{const id=b.dataset.hailEnd;ctx.modal('Qui ha smesso?',`<p>Confermi che, dal tuo punto di osservazione, non sta più grandinando? L’aggiornamento sarà pubblico e non dichiara sicura l’intera zona.</p>`,async()=>{await ctx.api('hail/end',{id,confirm:true});sequence++;busy=false;data=null;await load(true);ctx.toast('Osservazione aggiornata: l’autore riferisce che ha smesso.');return true})});
 }
 async function share(){const place=ctx.get().place,url=sharedHailURL(location.origin,place);if(!url){ctx.toast('Scegli prima una località da condividere.');return}const s=state(),text=`MeteoSocial · Grandine nella zona di ${place.name}\nConsultato il ${new Date().toISOString()} (UTC).\n${s.fresh?s.shown+' segnalazioni nei filtri scelti':'Segnalazioni non disponibili'} · ultimi ${minutes} minuti · ${radius?'entro '+radius+' km':'tutte le zone'}.\nFiltri: ${size==='all'?'tutte le dimensioni':HAIL_SIZE_LABELS[size]}; ${ended==='all'?'tutti gli stati':ended==='ended'?'fine riferita':'senza fine riferita'}.\nTestimonianze, non allerte ufficiali. Nessuna segnalazione non significa nessun rischio.\nIl link apre la zona approssimata con filtri standard e dati aggiornati, che possono differire:\n${url}`;
 if(navigator.share)try{await navigator.share({title:'MeteoSocial · Grandine',text});return}catch(e){if(e.name==='AbortError')return}try{await navigator.clipboard.writeText(text);ctx.toast('Zona e riepilogo copiati.')}catch{ctx.modal('Copia la zona',`<label class="field"><span>Seleziona e copia il riepilogo</span><textarea readonly rows="10">${esc(text)}</textarea></label>`,null)}}
 async function load(force=false){if(!visible||document.hidden)return;const id=ctx.get().me?.id||'';if(user!==id){sequence++;busy=false;data=null;user=id}if(busy||!force&&data&&Date.now()-data.updated<30000)return;busy=true;error='';const token=++sequence;paint();try{const d=await ctx.api('atlas/hail-map');if(token!==sequence||id!==(ctx.get().me?.id||''))return;if(!Array.isArray(d.posts)||!Number.isFinite(d.updated))throw Error('Dati incompleti');data=d;watch.update()}catch{if(token!==sequence)return;data=null;error='Connessione non disponibile: le segnalazioni non sono aggiornate. Premi Aggiorna ora.'}finally{if(token===sequence){busy=false;paint();ctx.onUpdate()}}}
 function bind(){if(!visible)return;for(const [selector,set] of [['#map-hail-minutes',v=>minutes=Number(v)],['#map-hail-radius',v=>radius=Number(v)],['#map-hail-ended',v=>ended=v],['#map-hail-size',v=>size=v]]){const el=document.querySelector(selector);if(el)el.onchange=()=>{set(el.value);paint();ctx.onUpdate()}}const refresh=document.querySelector('[data-map-hail-refresh]');if(refresh)refresh.onclick=()=>load(true);const shareButton=document.querySelector('[data-map-hail-share]');if(shareButton)shareButton.onclick=share;const compare=document.querySelector('#hail-radar-compare');if(compare)compare.onchange=()=>ctx.setRadar?.(compare.checked);paint();watch.bind();load()}
 setInterval(()=>{if(visible&&!document.hidden){paint();ctx.onUpdate();load(true)}},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&visible){paint();ctx.onUpdate();load(true)}});
 return {controls,list,bind,open,paint,watchHTML:()=>watch.shell(),points:()=>state().points,setVisible(value){visible=value},invalidate(){sequence++;busy=false;data=null;error='';if(visible){paint();ctx.onUpdate();load(true)}}};
}
